bench_run = function(d) {
	se_one = function(row_weights) {
		idx_t = d$w == 1
		idx_c = d$w == 0
		valid = is.finite(d$y) & is.finite(d$dead) & is.finite(row_weights) & row_weights > 0
		if (!any(valid & idx_t) || !any(valid & idx_c)) return(NA_real_)
		tau = min(max(d$y[valid & idx_t]), max(d$y[valid & idx_c]))
		if (!is.null(d$rmst_tau)) tau = min(tau, d$rmst_tau)
		arm_var = function(sel){
			y = d$y[sel]; dd = as.numeric(d$dead[sel]); wt = as.numeric(row_weights[sel])
			ut = sort(unique(y))
			n_j = vapply(ut, function(t) sum(wt[y >= t]), numeric(1L))
			d_j = vapply(ut, function(t) sum(wt[y == t & dd == 1]), numeric(1L))
			ev = d_j > 0 & ut < tau
			if (!any(ev)) return(0)
			t_e = ut[ev]; n_e = n_j[ev]; d_e = d_j[ev]
			S_after = cumprod(1 - d_e / n_e)
			A = rev(cumsum(rev(S_after * (c(t_e[-1L], tau) - t_e))))
			ok = n_e - d_e > 1e-12 * n_e
			sum(A[ok]^2 * d_e[ok] / (n_e[ok] * (n_e[ok] - d_e[ok])))
		}
		se = sqrt(arm_var(valid & idx_t) + arm_var(valid & idx_c))
		if (is.finite(se) && se > 0) se else NA_real_
	}
	vapply(d$rw, se_one, numeric(1L))
}

